-- Уникальность ключа и пары родителей; отсутствие потерянных ссылок.
SELECT count(*) AS n FROM (SELECT link_hk AS k FROM {{target:oil_dds__link_production_day_well}} GROUP BY link_hk HAVING link_hk IS NULL OR count(*)>1 UNION ALL SELECT min(link_hk) AS k FROM {{target:oil_dds__link_production_day_well}} GROUP BY production_hk,well_hk HAVING count(*)>1 UNION ALL SELECT l.link_hk AS k FROM {{target:oil_dds__link_production_day_well}} l LEFT JOIN {{target:oil_dds__hub_production_day}} p ON p.production_hk=l.production_hk LEFT JOIN {{target:oil_dds__hub_well}} w ON w.well_hk=l.well_hk WHERE p.production_hk IS NULL OR w.well_hk IS NULL) q;
